"""Separate B/C descriptive tables only after every eligible cell reconciles.
Analysis is frozen; raw evidence/projections and unknown grades/costs stay explicit.
"""
import argparse,json,pathlib
from native import H,sha

def render(source,analysis,independent):
 data=json.loads(pathlib.Path(source).read_text());primary=json.loads(pathlib.Path(analysis).read_text());check=json.loads(pathlib.Path(independent).read_text());assert check['verified'] and not check['errors'];assert primary['input_sha256']==sha(source) and check['input_sha256']==sha(source) and check['primary_analysis_sha256']==sha(analysis)
 plan=json.loads((H/'preregistration.json').read_text());outputs={}
 def value(x):return 'Unavailable' if x is None else format(x,',.6f') if isinstance(x,float) else str(x)
 for part,expected in [('B',108),('C',72)]:
  eligible=[c for c in data['cells'] if c['part']==part and c['eligibility']=='control_valid'];assert len(eligible)==expected and all(c['attempts'] for c in eligible);result=primary['parts'][part];assert result['bootstrap_draws']==20000;assert result['seed']=={'B':2026101212,'C':2026101213}[part];assert result['task_clusters']=={'B':9,'C':18}[part]
  text=[f'# G4 Part {part} — descriptive results','',f'All{expected} control-valid cells are attempted. No gate, early stop, promotion, shipment or push. G1–G3 and Part A remain separate.','', '| Arm | Cells | All attempts | Solves | Failures | Unknown grades | All-attempt provider tokens | Known lower bound | Unknown-cost attempts | Tokens/verified solve | Native/grader timeouts |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---|']
  for arm,r in result['arms'].items():text.append('|'+ '|'.join(map(str,[arm,r['cells'],r['attempts'],r['solves'],r['failures'],r['unknown_grades'],value(r['all_attempt_provider_tokens']),r['known_tokens'],r['unknown_cost_attempts'],value(r['tokens_per_verified_solve']),str(r['native_timeouts'])+'/'+str(r['grader_timeouts'])]))+'|')
  text+=['','## Paired task-cluster comparisons','',f"20,000 draws; seed{result['seed']}. All rounds/retries retained together. Undefined draws stay null, not zero. Ratios are tokens-per-verified-solve arm/baseline; no savings gate.",'','| Comparison | Point |95% interval on defined draws | Defined | Undefined | Conditional interval |','|---|---:|---|---:|---:|---|']
  for name,r in result['comparisons'].items():text.append('|'+ '|'.join(map(str,[name,value(r['point']),'['+','.join(value(x) for x in r['bootstrap95'])+']',r['defined_draws'],r['undefined_draws'],r['interval_conditional_on_defined_draws']]))+'|')
  text+=['','## Scope and limitations','', 'Codex0.160.0, unchanged shipped ours SHA68ea78dc and frozen G2 K. Same logical Qwen model including the two user-declared labels; response model/usage remains in every receipt, no variant shares. Route127.0.0.1:8000 only; shared16 rolling occupied slots, fresh all-backends waiting0 admission. Caps60 requests/7200s/16384 output. All attempts, errors, caps and infrastructure retries are charged; no model-error/cap reruns or cost imputation. Unknown grades are not asserted failures or solves. Runtime/load and execution-window effects limit causal claims.','']
  if part=='B':text+=['Nine original newly unsealed Terminal tasks×3 rounds×4 arms. Original gold/no-op controls retained. Missing tmux and Python relay-runtime environment prerequisites repaired neutrally before inference, paired controls rechecked; identical immutable task image across arms. Hidden original verifier is mounted only after native capture.','']
  else:text+=['Fixed30 fresh SWE Verified tasks, seed2026101204, no replacement/readiness filtering. Original six overlap the exposed18 and are not double-subtracted.18 gold/no-op-control-valid tasks yield72 cells;12 failed-control exclusions retain48 prospective queue cells. Quality is conditional on these18 tasks and the offline resource/cache environment, not the entire500-task benchmark. All original/uniform offline control outcomes preserved. First-window eight mkdir grader-launch errors were retained and uniformly resolved by captured-patch-only regrade with the unchanged official adapter; no actor/model rerun, all costs retained. Subsequent windows use the prospectively committed root fix.','']
  text+=['## Evidence','',f'Canonical input SHA `{sha(source)}`; frozen analyzer SHA `{primary["analysis_source_sha256"]}`; primary analysis SHA `{sha(analysis)}`; independent analysis SHA `{sha(independent)}`. Independent task-weight resampling verifies every draw/all-attempt metric. Canonical provenance links each audited window, raw receipts, native/capture hashes and explicit grade repairs. Original controls/graders and actual cleanup/integrity must also pass the final requirement audit; these tables alone are not completion.',''];outputs[part]='\n'.join(text)
 return outputs
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('input');p.add_argument('analysis');p.add_argument('independent');a=p.parse_args()
 for part,text in render(a.input,a.analysis,a.independent).items():(H/f'report-{part}.md').write_text(text)
